  var VT = { think: '思考中', exec: '执行中' };
  var TZ = { READ: '读取', GREP: '检索', GLOB: '检索', LIST: '检索', EDIT: '改写', PATCH: '改写', WRITE: '写入', BASH: '执行', WEB: '联网', TODO: '规划', UNIT: '出击', WAIT: '等候', ASK: '询问', IMAGE: '读图', SKILL: '技能' };
  var FXL = { full: '全效', lite: '简洁', off: '关' };
  var FX_NEXT = { full: 'lite', lite: 'off', off: 'full' };
  var pad2 = function (n) { return String(n).padStart(2, '0'); };
  var fmtT = function (ms) { var s = Math.max(0, ms || 0) / 1000; return pad2(Math.floor(s / 60)) + ':' + (s % 60).toFixed(2).padStart(5, '0'); };
