    thunk: function () { this.tone(72, 0.55, { vol: 0.28, slide: 0.5 }); this.noise(0.18, { vol: 0.07, hp: 200 }); },
    blip: function () { this.tone(1320, 0.07, { type: 'triangle', vol: 0.05 }); this.tone(1980, 0.05, { type: 'triangle', vol: 0.03, at: 0.05 }); },
    alarm: function () { for (var i = 0; i < 4; i++) { this.tone(880, 0.16, { type: 'square', vol: 0.03, at: i * 0.36 }); this.tone(660, 0.16, { type: 'square', vol: 0.03, at: i * 0.36 + 0.18 }); } },
