      pf: q('.eva-pfeed'), pfImg: q('.eva-pfeed img'), pfZh: q('.eva-pfeed .pff b'), pfEn: q('.eva-pfeed .pff span'), pfRep: q('.eva-pfeed .pfr'),
      ap: q('.eva-ap'), apTool: q('.aptool'), apCmd: q('.apcmd'), apWhy: q('.apwhy'), rvs: root.querySelectorAll('.rv'), tally: q('.tally'), hintTool: q('.hinttool'),
      gb: q('.eva-gbands'), card: q('.eva-card'), cPic: q('.eva-card .pic'), cK: q('.tc .k'), cA: q('.tc .a'), cB: q('.tc .b'), cC: root.querySelectorAll('.tc .c span'),
